{"thought": "I now have all the info I need. Let me implement paid_hours. Logic: for each worker, parse each shift with parse_shift (returns day_index, start, end in minutes). Duration = end - start. If duration > 360 (6h), deduct 30 min. Sum all, format with format_duration. Worker with no shifts gets '0m'. Raise ValueError if entry can't be parsed.", "action": {"tool": "write_file", "args": {"path": "src/slotplan/paid_hours.py", "content": "from __future__ import annotations

from typing import Dict, Mapping, Sequence

from slotplan.format_duration import format_duration
from slotplan.parse_shift import parse_shift


def paid_hours(rota: Mapping[str, Sequence[str]]) -> Dict[str, str]:
    """
    Compute each worker's paid working time for one week of rota entries
    (parsed with parse_shift) and return it formatted with format_duration, e.g.
    {"kim": "38h 30m"}. Every worker in `rota` appears in the result; a worker
    with no shifts gets "0m".

    Raise ValueError if an entry cannot be parsed.

    Example:
        paid_hours({"kim": ["Mon 09:00-13:00", "Tue 13:00-17:30"]}) == {"kim": "8h 30m"}
    """
    result: Dict[str, int] = {}
    for worker, shifts in rota.items():
        total = 0
        for entry in shifts:
            _, start, end = parse_shift(entry)
            duration = end - start
            if duration > 360:
                duration -= 30
            total += duration
        result[worker] = total
    return {worker: format_duration(mins) for worker, mins in result.items()}
"}}, "messages": []}

